S="C:/Users/18500/AppData/Local/Temp/claude/d3bb15cb111f6f8b/c60a2e49-7b3b-480d-be84-786f7790d5b7/scratchpad"; R="C:/Users/18500/Desktop/7270/Assignment5/walker-mimic-keep-rui-sun/captures/impact_burst"; cat > "$S/cmp.gd" <<'EOF'
extends SceneTree
func _md(a: Color, b: Color) -> float:
	return maxf(maxf(absf(a.r-b.r), absf(a.g-b.g)), absf(a.b-b.b)) * 255.0
func _ld(p: String) -> Image:
	var im := Image.load_from_file(p); im.convert(Image.FORMAT_RGB8); return im
func _init():
	var a: String = OS.get_cmdline_user_args()[0]; var b: String = OS.get_cmdline_user_args()[1]
	var ba := _ld("%s/frame%08d.png" % [a, 50]); var bb := _ld("%s/frame%08d.png" % [b, 50])
	var same_bg := 0
	for y in range(0, 720): for x in range(0, 1280):
		if _md(ba.get_pixel(x,y), bb.get_pixel(x,y)) > 0: same_bg += 1
	print("frame50 pixels differing r0t vs r1 (whole frame): ", same_bg)
	print("frame | vs own f50 >8/>40 r0t -> r1 | near-white(min ch>230) r0t -> r1 | sum of change r0t -> r1 | px differing r0t vs r1, max diff, mean diff over those")
	for f in [10, 12, 15, 20, 30, 50]:
		var ia := _ld("%s/frame%08d.png" % [a, f]); var ib := _ld("%s/frame%08d.png" % [b, f])
		var c8a := 0; var c40a := 0; var c8b := 0; var c40b := 0; var wa := 0; var wb := 0
		var sa := 0.0; var sb := 0.0; var nd := 0; var mx := 0.0; var sd := 0.0
		for y in range(400, 640): for x in range(540, 740):
			var pa := ia.get_pixel(x,y); var pb := ib.get_pixel(x,y)
			var da := _md(pa, ba.get_pixel(x,y)); var db := _md(pb, bb.get_pixel(x,y))
			if da > 8: c8a += 1
			if da > 40: c40a += 1
			if db > 8: c8b += 1
			if db > 40: c40b += 1
			sa += da; sb += db
			if minf(minf(pa.r,pa.g),pa.b)*255 > 230: wa += 1
			if minf(minf(pb.r,pb.g),pb.b)*255 > 230: wb += 1
			var d := _md(pa, pb)
			if d > 0: nd += 1; sd += d; mx = maxf(mx, d)
		print("%d | %d/%d -> %d/%d | %d -> %d | %d -> %d | %d, %.0f, %.1f" % [f, c8a, c40a, c8b, c40b, wa, wb, sa, sb, nd, mx, sd / maxf(nd, 1)])
	quit()
EOF
godot --headless --script "$S/cmp.gd" -- "$R/r0-tinted" "$R/r1" 2>&1 | grep -v "^Godot\|^$"

